def get_samples():
    samples = []
    for fam in FAMILIES:
        for text in fam['narratives']:
            samples.append({
                'text': text,
                'is_narrative': True,
                'scenario_family': fam['name'],
                'lineage_id': fam['id'],
                'narrative_style': fam['style'],
                'word_count': len(text.split())
            })
        for text in fam['concise']:
            samples.append({
                'text': text,
                'is_narrative': False,
                'scenario_family': fam['name'],
                'lineage_id': fam['id'],
                'narrative_style': 'concise_report',
                'word_count': len(text.split())
            })
    return samples

def get_narratives():
    res = []
